-- tts/lua/core.lua, inlined
Core = (function()
--[[ Hex-Nexus rules core: pure Lua 5.2, no Tabletop Simulator calls.

A port of the engine's round bookkeeping, so the table runs the same rules the
simulations were balanced on:

  Core.upkeep(state)   engine.game.upkeep (steps 1-8), with abilities.respawn,
                       move_waves, spawn_waves, decay_structures
  Core.world(state)    engine.game.world_phase, then the flip checkpoint
  Core.refresh(state)  engine.state.refresh_visibility / place_units_on_flip
  Core.killChampion    engine.resolve.kill_champion (+ the designer's Baron rule)
  Core.tiebreak(state) engine.run.Game._tiebreak

The Global script reads the table into a `state` table, calls these, and
writes the result back. tts/tests/run.lua replays engine scenarios through the
same functions (the parity harness), so a rules difference shows up there,
not at the table.

State shape (every list keeps the engine's order; hexes are {q, r}):
  round, priority ("north"|"south"), next_uid, winner, end_reason
  hidden    = {[tile name] = true}       hidden hexgroups
  wards     = {[tile name] = round}      Control Wards
  champs    = {{uid, cid, team, hp, max_hp, hex, alive, track, shield,
                shield_until, items = {name = true}}}
  waves     = {{uid, team, lane, chips, path_idx (0-based), hex, empowered}}
  structures= {{uid, team, stype, lane, tier, chips, hex, alive}}
  monsters  = {{uid, mtype, chips, max_chips, hex, alive, respawn_round}}
  teams     = {north = {ap, kills, towers_lost, baron, dragons,
                         dragon_track = {..}, cards = {name = n}}, south = ..}

Options (designer rulings that the engine does not have yet):
  kill_includes_baron  a kill by a Baron holder pays two Empowered waves
  monster_heal         a monster that survives a round is back to full HP
]]

local Core = {}
Core.__index = Core

local TEAMS = {"north", "south"}
local DIRS = {{1, 0}, {1, -1}, {0, -1}, {-1, 0}, {-1, 1}, {0, 1}}
local DEATH_BANDS = {{4, 2}, {8, 3}, {math.huge, 4}}       -- engine.resolve.DEATH_BANDS

local function key(h) return h[1] .. "," .. h[2] end
local function other(team) if team == "north" then return "south" end return "north" end
Core.other = other
Core.key = key

local function hexDistance(a, b)
  local dq, dr = a[1] - b[1], a[2] - b[2]
  return math.max(math.abs(dq), math.abs(dr), math.abs(-dq - dr))
end
Core.hexDistance = hexDistance

local function sortHexes(list)
  table.sort(list, function(a, b)
    if a[1] ~= b[1] then return a[1] < b[1] end
    return a[2] < b[2]
  end)
  return list
end

-- Stable sort (Python's sorted is stable; table.sort is not).
local function stableSort(list, less)
  local idx = {}
  for i, v in ipairs(list) do idx[v] = i end
  table.sort(list, function(a, b)
    if less(a, b) then return true end
    if less(b, a) then return false end
    return idx[a] < idx[b]
  end)
  return list
end

-- ------------------------------------------------------------------- board
function Core.new(map, config, opts)
  local self = setmetatable({map = map, cfg = config, opts = opts or {}}, Core)
  self.tileNames, self.tileOf, self.tileHexes, self.onBoard = {}, {}, {}, {}
  for name in pairs(map.hexgroups) do self.tileNames[#self.tileNames + 1] = name end
  table.sort(self.tileNames)
  for _, name in ipairs(self.tileNames) do
    local hs = {}
    for _, h in ipairs(map.hexgroups[name]) do
      hs[#hs + 1] = {h[1], h[2]}
      self.tileOf[key(h)] = name
      self.onBoard[key(h)] = true
    end
    self.tileHexes[name] = sortHexes(hs)
  end
  self.lanes = map.lane_order or {"top", "mid", "bot"}
  self.fountain, self.paths, self.baseTile = {}, {}, {}
  for _, team in ipairs(TEAMS) do
    local side = map[team]
    self.fountain[team] = {side.fountain[1], side.fountain[2]}
    self.baseTile[team] = self.tileOf[key(side.fountain)]
    self.paths[team] = {}
    for _, lane in ipairs(self.lanes) do
      local p = {}
      for _, h in ipairs(side.lane_paths[lane]) do p[#p + 1] = {h[1], h[2]} end
      self.paths[team][lane] = p
    end
  end
  return self
end

function Core:neighbors(h)
  local out = {}
  for _, d in ipairs(DIRS) do
    local n = {h[1] + d[1], h[2] + d[2]}
    if self.onBoard[key(n)] then out[#out + 1] = n end
  end
  return out
end

function Core:tile(h) return self.tileOf[key(h)] end

-- World (x, z) <-> hex, for the table adapter. North (negative r) is +Z.
function Core.hexToWorld(h, size)
  local q, r = h[1], h[2]
  return 1.5 * size * q, -math.sqrt(3) * size * (r + q / 2)
end

function Core:worldToHex(x, z, size)
  local q = x / (1.5 * size)
  local r = -z / (math.sqrt(3) * size) - q / 2
  -- cube rounding
  local cx, cz = q, r
  local cy = -cx - cz
  local rx, ry, rz = math.floor(cx + 0.5), math.floor(cy + 0.5), math.floor(cz + 0.5)
  local dx, dy, dz = math.abs(rx - cx), math.abs(ry - cy), math.abs(rz - cz)
  if dx > dy and dx > dz then rx = -ry - rz
  elseif dy > dz then ry = -rx - rz
  else rz = -rx - ry end
  local h = {rx + 0, rz + 0}          -- + 0 turns a rounded -0 into 0 for the key
  if self.onBoard[key(h)] then return h end
  return nil
end

-- ------------------------------------------------------------------- units
function Core:allUnits(s)
  local out = {}
  for _, c in ipairs(s.champs) do c.kind = "champion"; out[#out + 1] = c end
  for _, w in ipairs(s.waves) do w.kind = "wave"; w.alive = true; out[#out + 1] = w end
  for _, x in ipairs(s.structures) do x.kind = "structure"; out[#out + 1] = x end
  for _, m in ipairs(s.monsters) do m.kind = "monster"; out[#out + 1] = m end
  return out
end

local function isHidden(s, tile) return s.hidden[tile] == true end

function Core:nodeOf(s, h)
  local t = self:tile(h)
  if isHidden(s, t) then return "T:" .. t end
  return "H:" .. key(h)
end

function Core:unitsAtNode(s, node)
  local out = {}
  for _, u in ipairs(self:allUnits(s)) do
    if u.alive and self:nodeOf(s, u.hex) == node then out[#out + 1] = u end
  end
  return out
end

function Core:canStop(s, node, team)
  local us = self:unitsAtNode(s, node)
  if node:sub(1, 2) == "T:" then
    for _, u in ipairs(us) do if u.team ~= team then return false end end
    return true
  end
  return #us == 0
end

-- -------------------------------------------------------------- visibility
function Core:tileTeamSets(s)
  local out = {}
  for _, u in ipairs(self:allUnits(s)) do
    if u.alive and u.kind ~= "monster" then
      local t = self:tile(u.hex)
      out[t] = out[t] or {}
      out[t][u.team] = true
    end
  end
  return out
end

local function setSize(set)
  local n = 0
  for _ in pairs(set or {}) do n = n + 1 end
  return n
end

function Core:watched(s, sets)
  local w = {}
  if self.cfg.adjacency_reveal == false then return w end
  local radius = self.cfg.reveal_radius or 1
  for _, c in ipairs(s.champs) do
    if c.alive then
      local near, list = {}, {}
      for _, n in ipairs(self:neighbors(c.hex)) do
        if not near[key(n)] then near[key(n)] = true; list[#list + 1] = n end
      end
      for _ = 1, radius - 1 do
        local snapshot = {}
        for i = 1, #list do snapshot[i] = list[i] end
        for _, h in ipairs(snapshot) do
          for _, n in ipairs(self:neighbors(h)) do
            if not near[key(n)] then near[key(n)] = true; list[#list + 1] = n end
          end
        end
      end
      for _, nb in ipairs(list) do
        local t = self:tile(nb)
        if t and not w[t] then
          for team in pairs(sets[t] or {}) do
            if team ~= c.team then w[t] = true; break end
          end
        end
      end
    end
  end
  return w
end

-- Rules 3.3 step 3 / 3.4: champions inside a newly visible tile take hexes.
function Core:placeOnFlip(s, tile, events)
  local hexes = self.tileHexes[tile]
  local fixed, movable = {}, {}
  for _, u in ipairs(self:allUnits(s)) do
    if u.alive and self:tile(u.hex) == tile then
      if u.kind == "champion" then movable[#movable + 1] = u else fixed[key(u.hex)] = u end
    end
  end
  if #movable == 0 then return end
  local free = {}
  for _, h in ipairs(hexes) do if not fixed[key(h)] then free[#free + 1] = h end end
  local isFree = {}
  for _, h in ipairs(free) do isFree[key(h)] = true end
  local assigned, taken = {}, {}
  for _, c in ipairs(movable) do
    if isFree[key(c.hex)] and not taken[key(c.hex)] then
      assigned[c] = c.hex; taken[key(c.hex)] = true
    end
  end
  for _, c in ipairs(movable) do
    if not assigned[c] then
      local spot
      for _, h in ipairs(free) do if not taken[key(h)] then spot = h; break end end
      if not spot then
        for _, h in ipairs(hexes) do
          for _, nb in ipairs(self:neighbors(h)) do
            if self:tile(nb) ~= tile and not spot and not taken[key(nb)]
                and #self:unitsAtNode(s, self:nodeOf(s, nb)) == 0 then
              spot = nb
            end
          end
        end
        spot = spot or c.hex
      end
      assigned[c] = spot; taken[key(spot)] = true
    end
  end
  for _, c in ipairs(movable) do
    if key(assigned[c]) ~= key(c.hex) and events then
      events[#events + 1] = {t = "place", uid = c.uid, from = c.hex, to = assigned[c]}
    end
    c.hex = assigned[c]
  end
end

function Core:forceVisible(s, tile, events)
  if isHidden(s, tile) then
    s.hidden[tile] = nil
    if events then events[#events + 1] = {t = "flip", tile = tile, visible = true} end
    self:placeOnFlip(s, tile, events)
  end
end

function Core:refresh(s, allowFlipBack, events)
  local sets = self:tileTeamSets(s)
  local watched = self:watched(s, sets)
  local newly = {}
  for _, t in ipairs(self.tileNames) do
    local contested = setSize(sets[t]) > 1 or watched[t]
    local warded = (s.wards and s.wards[t] or -1) >= s.round
    local hidden = isHidden(s, t)
    if hidden and (contested or warded) then
      s.hidden[t] = nil
      newly[#newly + 1] = t
      if events then events[#events + 1] = {t = "flip", tile = t, visible = true} end
    elseif not hidden and allowFlipBack ~= false and not contested and not warded then
      s.hidden[t] = true
      if events then events[#events + 1] = {t = "flip", tile = t, visible = false} end
    end
  end
  for _, t in ipairs(newly) do self:placeOnFlip(s, t, events) end
end

-- ----------------------------------------------------------------- numbers
function Core:waveSize(round)
  local c = self.cfg
  if c.wave_growth_round2 and round >= c.wave_growth_round2 then return c.wave_chips_late2 end
  if round >= c.wave_growth_round then return c.wave_chips_late end
  return c.wave_chips
end

function Core:deathPosition(round)
  local band = 3
  if round <= DEATH_BANDS[1][1] then band = 1 elseif round <= DEATH_BANDS[2][1] then band = 2 end
  local pos = self.cfg.death_track_positions
  if pos then return pos[band] end
  return DEATH_BANDS[band][2] + (self.cfg.death_band_bonus or 0)
end

function Core:killReward(s, team)
  local mult = self.cfg.kill_ap_waves or 0
  if mult > 0 then
    local size = self:waveSize(s.round)
    if self.opts.kill_includes_baron and team and s.teams[team].baron then
      size = size + self.cfg.baron_wave_bonus
    end
    return math.floor(mult * size + 0.5)
  end
  return self.cfg.kill_ap or 1
end

-- ------------------------------------------------------------- kill / hits
function Core:killChampion(s, victim, killerTeam, events)
  victim.alive = false
  victim.hp = 0
  victim.shield = 0
  victim.track = self:deathPosition(s.round)
  local reward = 0
  if killerTeam then
    reward = self:killReward(s, killerTeam)
    s.teams[killerTeam].ap = s.teams[killerTeam].ap + reward
    s.teams[killerTeam].kills = s.teams[killerTeam].kills + 1
  end
  if events then
    events[#events + 1] = {t = "kill", uid = victim.uid, team = killerTeam, ap = reward,
                           track = victim.track}
  end
end

function Core:monsterReward(s, m, team, events)
  local ts = s.teams[team]
  ts.cards = ts.cards or {}
  if m.mtype == "blue_buff" or m.mtype == "red_buff" then
    ts.cards[m.mtype] = (ts.cards[m.mtype] or 0) + 1
  elseif m.mtype == "dragon" then
    ts.dragons = (ts.dragons or 0) + 1
    if self.cfg.dragon_card and ts.dragons <= (self.cfg.dragon_cap or 2) then
      ts.cards.dragon = (ts.cards.dragon or 0) + 1
    end
  elseif m.mtype == "baron" then
    ts.baron = true
  end
  if events then events[#events + 1] = {t = "reward", mtype = m.mtype, team = team} end
end

function Core:destroy(s, target, team, events)
  target.alive = false
  if target.kind == "wave" then
    for i, w in ipairs(s.waves) do if w == target then table.remove(s.waves, i); break end end
    if events then events[#events + 1] = {t = "wave_down", uid = target.uid} end
  elseif target.kind == "structure" then
    if target.stype == "nexus" then
      s.winner = other(target.team)
      s.end_reason = "nexus"
    else
      s.teams[target.team].towers_lost = s.teams[target.team].towers_lost + 1
      local reward = self.cfg.tower_kill_ap or 0
      if team and reward > 0 then s.teams[team].ap = s.teams[team].ap + reward end
    end
    if events then events[#events + 1] = {t = "structure_down", uid = target.uid, team = team} end
  elseif target.kind == "monster" then
    if team then self:monsterReward(s, target, team, events) end
    target.respawn_round = s.round + self.cfg.monsters[target.mtype].respawn
    if events then events[#events + 1] = {t = "monster_down", uid = target.uid, team = team} end
  end
end

-- World Phase damage (no champion source: chips go to the supply).
function Core:dealHits(s, team, target, k, events)
  if k <= 0 or not target.alive then return end
  if target.kind == "champion" then
    local absorbed = 0
    if (target.shield or 0) > 0 and (target.shield_until or 0) >= s.round then
      absorbed = math.min(target.shield, k)
      target.shield = target.shield - absorbed
    end
    local dmg = k - absorbed
    if dmg <= 0 then return end
    target.hp = target.hp - dmg
    if events then events[#events + 1] = {t = "hit", uid = target.uid, k = dmg} end
    if target.hp <= 0 then self:killChampion(s, target, team, events) end
    return
  end
  local chips = math.min(k, target.chips)
  target.chips = target.chips - chips
  if events then events[#events + 1] = {t = "hit", uid = target.uid, k = chips} end
  if target.chips <= 0 then self:destroy(s, target, team, events) end
end

-- ------------------------------------------------------------------ Upkeep
function Core:respawn(s, c)
  local home = self.fountain[c.team]
  local baseTile = self.baseTile[c.team]
  local baseHexes = {home}
  for _, h in ipairs(self.tileHexes[baseTile]) do
    if key(h) ~= key(home) then baseHexes[#baseHexes + 1] = h end
  end
  local ring, inRing = {}, {}
  for _, h in ipairs(self.tileHexes[baseTile]) do
    for _, nb in ipairs(self:neighbors(h)) do
      if self:tile(nb) ~= baseTile and not inRing[key(nb)] then
        ring[#ring + 1] = nb; inRing[key(nb)] = true
      end
    end
  end
  local units = self:allUnits(s)
  local function empty(h)
    for _, u in ipairs(units) do
      if u.alive and key(u.hex) == key(h) then return false end
    end
    return true
  end
  local function legal(h) return self:canStop(s, self:nodeOf(s, h), c.team) end
  local spot
  if legal(home) then spot = home end
  if not spot then
    for _, h in ipairs(baseHexes) do if empty(h) and legal(h) then spot = h; break end end
  end
  if not spot and isHidden(s, baseTile) then
    for _, h in ipairs(baseHexes) do if legal(h) then spot = h; break end end
  end
  if not spot then
    for _, h in ipairs(ring) do if empty(h) and legal(h) then spot = h; break end end
  end
  if not spot then return false end
  c.hex = {spot[1], spot[2]}
  c.alive = true
  c.hp = c.max_hp
  c.shield = 0
  return true
end

function Core:decay(s, events)
  local c = self.cfg
  local step = c.structure_decay or 0
  local every = math.max(1, c.structure_decay_every or 1)
  if step == 0 or s.round < 2 or (s.round - 1) % every ~= 0 then return end
  local base = c.structure_decay_floor or 1
  local floors = {tower = c.tower_decay_floor or base, nexus = c.nexus_decay_floor or base}
  for _, x in ipairs(s.structures) do
    local floor = floors[x.stype]
    if x.alive and x.chips > floor then
      local before = x.chips
      x.chips = math.max(floor, x.chips - step)
      if events then events[#events + 1] = {t = "decay", uid = x.uid, from = before, to = x.chips} end
    end
  end
end

function Core:moveWaves(s, team, events)
  local mine = {}
  for _, w in ipairs(s.waves) do if w.team == team then mine[#mine + 1] = w end end
  stableSort(mine, function(a, b) return a.path_idx > b.path_idx end)
  for _, w in ipairs(mine) do
    local path = self.paths[team][w.lane]
    local steps = self.cfg.wave_speed
    local landed, pos = w.path_idx, w.path_idx
    for _ = 1, steps do
      if pos + 1 >= #path then break end
      local nxt = path[pos + 2]
      local node = self:nodeOf(s, nxt)
      local isTile = node:sub(1, 2) == "T:"
      local units = {}
      for _, u in ipairs(self:unitsAtNode(s, node)) do
        if u ~= w and (isTile or key(u.hex) == key(nxt)) then units[#units + 1] = u end
      end
      local enemyInside = false
      for _, u in ipairs(units) do
        if u.team ~= nil and u.team ~= team then enemyInside = true end
      end
      if isTile and enemyInside then
        self:forceVisible(s, self:tile(nxt), events)
        break
      end
      local blocked = false
      for _, u in ipairs(units) do
        if (u.team ~= nil and u.team ~= team) or u.kind == "monster" then blocked = true end
      end
      if blocked then break end
      pos = pos + 1
      local friend = false
      for _, u in ipairs(self:unitsAtNode(s, self:nodeOf(s, nxt))) do
        if u ~= w and key(u.hex) == key(nxt) and u.team == team then friend = true end
      end
      if not friend then landed = pos end
    end
    if landed ~= w.path_idx then
      if events then
        events[#events + 1] = {t = "wave_move", uid = w.uid, from = w.hex, to = path[landed + 1]}
      end
      w.path_idx = landed
      w.hex = {path[landed + 1][1], path[landed + 1][2]}
    end
  end
end

function Core:spawnWaves(s, events)
  local size = self:waveSize(s.round)
  for _, team in ipairs(TEAMS) do
    local bonus = s.teams[team].baron and self.cfg.baron_wave_bonus or 0
    for _, lane in ipairs(self.lanes) do
      local hex = self.paths[team][lane][1]
      local node = self:nodeOf(s, hex)
      local occupants, friendly = {}, nil
      for _, u in ipairs(self:unitsAtNode(s, node)) do
        if key(u.hex) == key(hex) then
          occupants[#occupants + 1] = u
          if u.kind == "wave" and u.team == team and not friendly then friendly = u end
        end
      end
      if friendly then
        friendly.chips = friendly.chips + size + bonus
        if events then events[#events + 1] = {t = "wave_merge", uid = friendly.uid, add = size + bonus} end
      elseif #occupants == 0 then
        local uid = "w" .. s.next_uid
        s.next_uid = s.next_uid + 1
        local w = {uid = uid, team = team, lane = lane, chips = size + bonus, path_idx = 0,
                   hex = {hex[1], hex[2]}, empowered = s.teams[team].baron == true,
                   kind = "wave", alive = true}
        s.waves[#s.waves + 1] = w
        if events then events[#events + 1] = {t = "wave_spawn", uid = uid} end
      end
    end
  end
end

function Core:upkeep(s)
  local cfg, events = self.cfg, {}
  -- Designer: a monster that was hit but not killed is back to full at the
  -- end of the round (the start of this Upkeep).
  if self.opts.monster_heal then
    for _, m in ipairs(s.monsters) do
      if m.alive and m.chips < m.max_chips then
        events[#events + 1] = {t = "monster_heal", uid = m.uid, from = m.chips, to = m.max_chips}
        m.chips = m.max_chips
      end
    end
  end
  s.round = s.round + 1                                   -- step 1
  if s.round > 1 then s.priority = other(s.priority) end
  for _, c in ipairs(s.champs) do                         -- step 2
    if (c.track or 0) > 0 then c.track = c.track - 1 end
    if c.track == 0 and not c.alive then
      if self:respawn(s, c) then events[#events + 1] = {t = "respawn", uid = c.uid, hex = c.hex} end
    end
    if (c.shield_until or 0) < s.round then c.shield = 0 end
  end
  for _, team in ipairs(TEAMS) do
    local ts = s.teams[team]
    if ts.dragon_track and #ts.dragon_track > 0 then
      local keep, back = {}, 0
      for _, p in ipairs(ts.dragon_track) do
        if p - 1 > 0 then keep[#keep + 1] = p - 1 else back = back + 1 end
      end
      ts.dragon_track = keep
      ts.cards = ts.cards or {}
      if back > 0 then ts.cards.dragon = (ts.cards.dragon or 0) + back end
    end
  end
  for _, c in ipairs(s.champs) do                         -- step 3
    if c.alive and self:tile(c.hex) == self.baseTile[c.team] and c.hp ~= c.max_hp then
      events[#events + 1] = {t = "heal", uid = c.uid, from = c.hp, to = c.max_hp}
      c.hp = c.max_hp
    end
  end
  self:decay(s, events)
  for _, team in ipairs(TEAMS) do                         -- step 4
    local ts = s.teams[team]
    ts.ap = cfg.ap_base + math.min(ts.dragons or 0, cfg.dragon_cap) * (cfg.dragon_ap_each or 1)
  end
  self:moveWaves(s, s.priority, events)                   -- step 5
  self:moveWaves(s, other(s.priority), events)
  self:refresh(s, true, events)
  if s.round % 2 == 1 or not cfg.wave_spawn_odd_rounds_only then  -- step 6
    self:spawnWaves(s, events)
  end
  for _, m in ipairs(s.monsters) do                       -- step 7
    if not m.alive and s.round >= m.respawn_round then
      local blocked = false
      for _, u in ipairs(self:allUnits(s)) do
        if u.alive and u ~= m and key(u.hex) == key(m.hex) then blocked = true end
      end
      if not blocked then
        m.alive = true
        m.chips = m.max_chips
        events[#events + 1] = {t = "monster_spawn", uid = m.uid}
      end
    end
  end
  self:refresh(s, true, events)                           -- step 8
  return events
end

-- --------------------------------------------------------------- World
function Core:concealed(s, u, srcTile)
  if u.kind ~= "champion" then return false end
  local t = self:tile(u.hex)
  return t ~= srcTile and isHidden(s, t)
end

function Core:effectAdjacent(s, u)
  local tile = self:tile(u.hex)
  local units = self:allUnits(s)
  local out, seen = {}, {}
  for _, o in ipairs(units) do
    if o ~= u and o.alive and self:tile(o.hex) == tile then out[#out + 1] = o; seen[o] = true end
  end
  for dq = -1, 1 do
    for dr = math.max(-1, -dq - 1), math.min(1, -dq + 1) do
      if dq ~= 0 or dr ~= 0 then
        local h = {u.hex[1] + dq, u.hex[2] + dr}
        for _, o in ipairs(units) do
          if o.alive and o ~= u and key(o.hex) == key(h) and not seen[o]
              and not self:concealed(s, o, tile) then
            out[#out + 1] = o; seen[o] = true
          end
        end
      end
    end
  end
  return out
end

function Core:structureTargetable(s, x)
  if x.stype == "tower" then
    if x.tier == 1 then return true end
    for _, y in ipairs(s.structures) do
      if y.team == x.team and y.stype == "tower" and y.lane == x.lane and y.tier == 1 then
        return not y.alive
      end
    end
    return true
  end
  local lanes = {}
  for _, y in ipairs(s.structures) do
    if y.team == x.team and y.stype == "tower" then
      lanes[y.lane] = lanes[y.lane] or {}
      table.insert(lanes[y.lane], y)
    end
  end
  for _, ts in pairs(lanes) do
    local down = true
    for _, y in ipairs(ts) do if y.alive then down = false end end
    if down then return true end
  end
  return false
end

function Core:canBeHitByWave(s, u, team)
  if not u.alive or u.team == team then return false end
  if u.kind == "structure" then return self:structureTargetable(s, u) end
  return true
end

function Core:world(s)
  local cfg, events, pending = self.cfg, {}, {}
  for _, w in ipairs(s.waves) do
    for _, u in ipairs(self:effectAdjacent(s, w)) do
      if self:canBeHitByWave(s, u, w.team) then
        local hits = 1
        if w.empowered and u.kind == "structure" then hits = 2 end
        pending[#pending + 1] = {u, hits, w.team}
      end
    end
  end
  for _, x in ipairs(s.structures) do
    if x.alive and x.stype == "tower" then
      for _, u in ipairs(self:effectAdjacent(s, x)) do
        if u.team ~= x.team and u.team ~= nil then
          if u.kind == "champion" then pending[#pending + 1] = {u, cfg.tower_hits_champion, x.team}
          elseif u.kind == "wave" then pending[#pending + 1] = {u, cfg.tower_hits_wave, x.team} end
        end
      end
    end
  end
  for _, m in ipairs(s.monsters) do
    if m.alive then
      for _, u in ipairs(self:effectAdjacent(s, m)) do
        if u.kind == "champion" then pending[#pending + 1] = {u, cfg.monster_hits, nil} end
      end
    end
  end
  local order, totals = {}, {}
  for _, p in ipairs(pending) do
    local u, k, team = p[1], p[2], p[3]
    if u.items and u.items.cloth_armor then k = math.max(0, k - 1) end
    if k > 0 then
      local cur = totals[u]
      if cur then cur[2] = cur[2] + k
      else totals[u] = {u, k, team}; order[#order + 1] = u end
    end
  end
  for _, u in ipairs(order) do
    local t = totals[u]
    if u.alive then self:dealHits(s, t[3], u, t[2], events) end
  end
  self:refresh(s, true, events)
  return events
end

-- ---------------------------------------------------------------- end
function Core:tiebreak(s)
  local lost = {north = s.teams.north.towers_lost, south = s.teams.south.towers_lost}
  if lost.north ~= lost.south then
    if lost.south > lost.north then return "north", "round_limit_towers" end
    return "south", "round_limit_towers"
  end
  local hp = {north = 0, south = 0}
  for _, x in ipairs(s.structures) do hp[x.team] = hp[x.team] + x.chips end
  if hp.north ~= hp.south then
    if hp.north > hp.south then return "north", "round_limit_hp" end
    return "south", "round_limit_hp"
  end
  local k = {north = s.teams.north.kills, south = s.teams.south.kills}
  if k.north ~= k.south then
    if k.north > k.south then return "north", "round_limit_kills" end
    return "south", "round_limit_kills"
  end
  return nil, "round_limit_draw"
end

return Core

end)()

--[[ Hex-Nexus Global script: table layout, panel and the referee.

Above this line: the generated tables (VERSION, CONFIG, MAP, ROSTER, ITEMS,
ROUNDS, LAYOUT, DASH, ...) from tools/tts_export.py, then the rules core
(tts/lua/core.lua) as `Core`. This file holds no game numbers of its own.

  * calibration: fit every generated object to the size it was drawn for and
    put it where it belongs;
  * the panel: versions, round, phase, priority, whose activation, AP;
  * the referee: Start game, then Next phase runs Upkeep and the World Phase
    through the core (the same rules as the Python engine, checked by
    tts/tests/run.lua) and writes the result back onto the table;
  * table events: HP clicks bank AP and handle kills, tower falls and
    monster rewards; card menus use abilities, play buffs, buy items;
  * hotkeys: flip the hexgroup under the cursor, map camera.
]]

local TEAMS = {"north", "south"}
local S = {round = 0, phase = 1, calibrated = false, flip = 0, panel = true, act = 1,
           started = false, priority = FIRST_PLAYER, next_uid = 1, picks = {north = {}, south = {}},
           teams = {}}

-- ------------------------------------------------------------------ utils
local function allObjects()
  if getObjects then return getObjects() end
  return getAllObjects()
end

local function tagOf(o)
  local ok, t = pcall(function() return o.getGMNotes() end)
  if ok and t then return t end
  return ""
end

local function findTag(tag)
  for _, o in ipairs(allObjects()) do
    if tagOf(o) == tag then return o end
  end
  return nil
end

local function other(team) if team == "north" then return "south" end return "north" end

local function seat(team) return SEATS[team] or team end

-- The designer fixed round 1 priority (FIRST_PLAYER); it alternates after.
local function priorityTeam()
  return S.priority or FIRST_PLAYER
end

-- ------------------------------------------------------------ calibration
-- Scale an object so its measured footprint matches the exporter's w x d,
-- then move it so its bounds (not its pivot) are centred on the target.
-- Height: objects that sit on another generated object (tiles on the mat,
-- pieces on the tiles) are stacked on its measured top surface, because TTS
-- decides how thick a custom tile or token really is.
function targetY(o, spec)
  if not spec.on then return spec.y end
  local base = findTag(spec.on)
  if not base then return spec.y end
  local bb = base.getBounds()
  local top = bb.center.y + bb.size.y / 2
  return top + o.getBounds().size.y / 2 + (spec.lift or 0.01)
end

local function fitObject(o, spec, place)
  if not o or not spec then return end
  if spec.w and spec.w > 0 then
    local b = o.getBoundsNormalized()
    local s = o.getScale()
    if b and b.size and b.size.x > 0.001 then
      local fx = spec.w / b.size.x
      local fz = fx
      if spec.d and spec.d > 0 and b.size.z > 0.001 then fz = spec.d / b.size.z end
      if math.abs(fx - 1) > 0.01 or math.abs(fz - 1) > 0.01 then
        o.setScale({s.x * fx, s.y, s.z * fz})
      end
    end
  end
  if place then
    local y = targetY(o, spec)
    o.setRotation({0, (spec.rot or 0) + (S.flip or 0), 0})
    o.setPosition({spec.x, y, spec.z})
    if spec.art then
      -- re-centre on the bounds once TTS has applied the new scale
      Wait.frames(function()
        if o == nil or o.isDestroyed and o.isDestroyed() then return end
        local c = o.getBounds().center
        local p = o.getPosition()
        local dx, dz = c.x - spec.x, c.z - spec.z
        if math.abs(dx) > 0.02 or math.abs(dz) > 0.02 then
          o.setPosition({p.x - dx, y, p.z - dz})
        end
      end, 3)
    end
    if spec.lock then o.setLock(true) end
  end
  local t = tagOf(o)
  if t:find("^hn:struct") or t:find("^hn:monster") or t:find("^hn:champ") or t:find("^hn:ap:")
      or t:find("^hn:wave:") then
    pcall(function() o.call("draw") end)       -- counter buttons follow the new scale
  end
end

local function loadingDone()
  for _, o in ipairs(allObjects()) do
    if o.loading_custom then return false end
  end
  return true
end

-- Pass `level` places the objects stacked `level` deep: 0 = on the table
-- (mat, dashboards, tracker), 1 = on the mat (tiles), 2 = on a tile (pieces).
-- Each level waits a few frames so the one below has its final size.
local function calibrateLevel(placeAll, level, n)
  for _, o in ipairs(allObjects()) do
    local spec = LAYOUT[tagOf(o)]
    if spec and (spec.level or 0) == level then
      fitObject(o, spec, placeAll and spec.start)
      n = n + 1
    end
  end
  if level < 2 then
    Wait.frames(function() calibrateLevel(placeAll, level + 1, n) end, 5)
    return
  end
  S.calibrated = true
  refreshUI()
  broadcastToAll("Hex-Nexus: laid out " .. n .. " objects.", {0.85, 0.77, 0.6})
end

local function doCalibrate(placeAll)
  calibrateLevel(placeAll, 0, 0)
end

function calibrate(placeAll)
  Wait.condition(function() doCalibrate(placeAll) end, loadingDone, 30,
    function() doCalibrate(placeAll) end)
end

-- Chips, standees and cards leave their bags at TTS's default size.
function onObjectLeaveContainer(_, o)
  local spec = LAYOUT[tagOf(o)]
  if spec and spec.w and spec.w > 0 then
    Wait.condition(function()
      if o and not o.isDestroyed() and (o.getQuantity() or -1) < 2 then fitObject(o, spec, false) end
    end, function() return o == nil or o.isDestroyed() or not o.loading_custom end, 10)
  end
end

-- Hexgroup flip: swap the tile's state and fit the new face.
function hnFlipTile(p)
  local o = getObjectFromGUID(p.guid)
  if not o then return end
  local id = o.getStateId()
  local n = o.setState(id == 1 and 2 or 1)
  if n then
    Wait.frames(function()
      local spec = LAYOUT[tagOf(n)]
      if spec then fitObject(n, spec, true) end
    end, 2)
  end
end

-- ------------------------------------------------------------------ helpers
local CORE = Core.new(MAP, CONFIG, {kill_includes_baron = true, monster_heal = true})
local HEX_SIZE = HEX
local ACTION, WORLD, SHOP, WINCHECK, UPKEEP = 2, 3, 4, 5, 1

local function tagged(prefix)
  local out = {}
  for _, o in ipairs(allObjects()) do
    if tagOf(o):sub(1, #prefix) == prefix then out[#out + 1] = o end
  end
  return out
end

local function get(o) return o and o.call("hnGet") or nil end

local function seatTeam(colour)
  if colour == SEATS.north then return "north" end
  if colour == SEATS.south then return "south" end
  return nil
end

-- Who a click helps: the clicker's team when they sit Blue or Red, otherwise
-- (hot-seat, spectators) whoever's activation it is.
local function actingTeam(colour)
  local t = seatTeam(colour)
  if t then return t end
  if S.phase == ACTION and SNAKE[S.act] == 2 then return other(priorityTeam()) end
  return priorityTeam()
end

local function apObj(team) return findTag("hn:ap:" .. team) end
local function getAP(team) local o = apObj(team); return o and o.call("hnGet") or 0 end
local function setAP(team, n) local o = apObj(team); if o then o.call("hnSet", n) end end
local function addAP(team, n) if team and n ~= 0 then setAP(team, getAP(team) + n) end end

local function teamState(team)
  S.teams[team] = S.teams[team] or {kills = 0, towers_lost = 0, baron = false, dragons = 0}
  return S.teams[team]
end

local function tileObj(name)
  return findTag("hn:tile:" .. name .. ":hidden") or findTag("hn:tile:" .. name .. ":visible")
end

-- Top surface height at a hex (its tile), so pieces are put down, not into.
local function surfaceY(hex)
  local t = tileObj(CORE:tile(hex))
  if t then local b = t.getBounds(); return b.center.y + b.size.y / 2 end
  return 1.3
end

local function moveToHex(o, hex)
  if not o then return end
  local x, z = Core.hexToWorld(hex, HEX_SIZE)
  o.setPositionSmooth({x, surfaceY(hex) + 0.4, z}, false, true)
end

local function dashY(team)
  local d = findTag("hn:art:dash:" .. team)
  if d then local b = d.getBounds(); return b.center.y + b.size.y / 2 end
  return 1.3
end

local function structureHex(team, key)
  if key == "nexus" then return MAP[team].nexus end
  return MAP[team].towers[key]
end

-- ---------------------------------------------------- table -> core state
local function readState()
  local s = {round = S.round, priority = priorityTeam(), next_uid = S.next_uid,
             winner = S.winner, end_reason = S.end_reason, hidden = {}, wards = {},
             champs = {}, waves = {}, structures = {}, monsters = {}, teams = {}}
  for _, o in ipairs(tagged("hn:tile:")) do
    local name, side = tagOf(o):match("^hn:tile:(.+):(%a+)$")
    if name and side == "hidden" then s.hidden[name] = true end
  end
  for _, team in ipairs(TEAMS) do
    for _, cid in ipairs(S.picks[team] or {}) do
      local so = findTag("hn:champ:" .. team .. ":" .. cid)
      local co = findTag("hn:card:champ:" .. team .. ":" .. cid)
      local cs, card = get(so) or {hp = 0, max = 1}, get(co) or {track = 0}
      local hex
      if so then local p = so.getPosition(); hex = CORE:worldToHex(p.x, p.z, HEX_SIZE) end
      local alive = so ~= nil and cs.hp > 0 and hex ~= nil and not card.dead
      s.champs[#s.champs + 1] = {
        uid = team .. ":" .. cid, cid = cid, team = team, hp = cs.hp, max_hp = cs.max,
        hex = hex or {CORE.fountain[team][1], CORE.fountain[team][2]}, alive = alive,
        track = card.track or 0, shield = 0, shield_until = 0, items = {},
        _obj = so, _card = co, _wasAlive = alive, _hexKey = hex and Core.key(hex) or "",
      }
    end
  end
  for _, o in ipairs(tagged("hn:wave:")) do
    local w = get(o)
    if w and w.uid then
      local path = CORE.paths[w.team][w.lane]
      local h = path[(w.path_idx or 0) + 1]
      s.waves[#s.waves + 1] = {uid = w.uid, team = w.team, lane = w.lane, chips = w.hp,
                               path_idx = w.path_idx or 0, hex = {h[1], h[2]},
                               empowered = w.empowered == true, _obj = o}
    end
  end
  table.sort(s.waves, function(a, b)
    return tonumber(a.uid:sub(2)) < tonumber(b.uid:sub(2))
  end)
  for _, o in ipairs(tagged("hn:struct:")) do
    local x = get(o)
    local team, key = tagOf(o):match("^hn:struct:(%a+):(.+)$")
    local h = structureHex(team, key)
    s.structures[#s.structures + 1] = {uid = x.uid, team = team, stype = x.stype, lane = x.lane,
                                       tier = x.tier, chips = x.hp, hex = {h[1], h[2]},
                                       alive = x.hp > 0, _obj = o}
  end
  table.sort(s.structures, function(a, b) return a.uid < b.uid end)
  for _, o in ipairs(tagged("hn:monster:")) do
    local m = get(o)
    local mtype, i = tagOf(o):match("^hn:monster:(.+):(%d+)$")
    local h = MAP.monsters[mtype][tonumber(i) + 1]
    s.monsters[#s.monsters + 1] = {uid = m.uid, mtype = mtype, chips = m.hp, max_chips = m.max,
                                   hex = {h[1], h[2]}, alive = m.hp > 0,
                                   respawn_round = m.respawn_round or 0, _obj = o}
  end
  for _, team in ipairs(TEAMS) do
    local ts = teamState(team)
    s.teams[team] = {ap = getAP(team), kills = ts.kills, towers_lost = ts.towers_lost,
                     baron = ts.baron, dragons = ts.dragons, dragon_track = {}, cards = {}}
  end
  return s
end

-- For tests and debugging: the table as the core sees it.
function hnDebugState() return readState() end

-- ---------------------------------------------------- core state -> table
local function handSpot(team)
  local d = DASH[team]
  S.hand = S.hand or {north = 0, south = 0}
  local i = S.hand[team] % 4
  S.hand[team] = S.hand[team] + 1
  local dx = (i - 1.5) * 1.35 * (d.rot == 0 and -1 or 1)
  return {d.hand.x + dx, dashY(team) + 0.5, d.hand.z}
end

local function dealCard(kind, team)
  local deck = findTag("hn:deck:buff:" .. kind)
  if not deck then
    broadcastToAll(seat(team) .. " takes a " .. kind .. " card (supply is out: take one by hand).",
      {1, 0.8, 0.4})
    return
  end
  deck.takeObject({position = handSpot(team), rotation = {0, DASH[team].rot, 0}, smooth = true,
                   callback_function = function(c) c.call("hnSet", {team = team}) end})
end

local function spawnWave(w)
  local tpl = WAVE_TEMPLATE[w.team][w.lane]
  local data = {}
  for k, v in pairs(tpl) do data[k] = v end
  data.GMNotes = "hn:wave:" .. w.uid
  data.LuaScriptState = JSON.encode({kind = "wave", label = SEATS[w.team] .. " " .. w.lane .. " wave",
                                     team = w.team, lane = w.lane, uid = w.uid, hp = w.chips,
                                     max = w.chips, path_idx = w.path_idx,
                                     empowered = w.empowered})
  local x, z = Core.hexToWorld(w.hex, HEX_SIZE)
  spawnObjectData({data = data, position = {x, surfaceY(w.hex) + 0.6, z},
                   rotation = {0, ART_ROT_Y, 0},
                   callback_function = function(o)
                     Wait.condition(function()
                       fitObject(o, {w = SIZES.wave, d = SIZES.wave}, false)
                     end, function() return o.isDestroyed() or not o.loading_custom end, 10)
                   end})
end

local function writeState(s, events)
  S.round, S.priority, S.next_uid = s.round, s.priority, s.next_uid
  S.winner, S.end_reason = s.winner, s.end_reason
  for _, team in ipairs(TEAMS) do
    local ts, t = teamState(team), s.teams[team]
    ts.kills, ts.towers_lost, ts.baron, ts.dragons = t.kills, t.towers_lost, t.baron, t.dragons
    setAP(team, t.ap)
  end
  for _, o in ipairs(tagged("hn:tile:")) do
    local name, side = tagOf(o):match("^hn:tile:(.+):(%a+)$")
    if name and (side == "hidden") ~= (s.hidden[name] == true) then
      hnFlipTile({guid = o.getGUID()})
    end
  end
  for _, c in ipairs(s.champs) do
    if c._card then c._card.call("hnSet", {track = c.track, dead = not c.alive}) end
    if c._obj then
      c._obj.call("hnSet", {hp = c.alive and c.hp or 0})
      if c.alive and (not c._wasAlive or Core.key(c.hex) ~= c._hexKey) then
        moveToHex(c._obj, c.hex)
      elseif not c.alive and c._wasAlive then
        local b = DASH[c.team].bench[ROSTER[c.cid].role]
        c._obj.setPositionSmooth({b.x, dashY(c.team) + 0.5, b.z}, false, true)
      end
    end
  end
  local keep = {}
  for _, w in ipairs(s.waves) do
    keep[w.uid] = true
    if w._obj then
      w._obj.call("hnSet", {hp = w.chips, path_idx = w.path_idx, empowered = w.empowered})
      moveToHex(w._obj, w.hex)
    else
      spawnWave(w)
    end
  end
  for _, o in ipairs(tagged("hn:wave:")) do
    local w = get(o)
    if w and w.uid and not keep[w.uid] then o.destruct() end
  end
  for _, x in ipairs(s.structures) do x._obj.call("hnSet", {hp = x.chips}) end
  for _, m in ipairs(s.monsters) do
    m._obj.call("hnSet", {hp = m.alive and m.chips or 0, respawn_round = m.respawn_round})
  end
  for _, e in ipairs(events or {}) do
    if e.t == "reward" then
      if e.mtype == "dragon" then
        if teamState(e.team).dragons <= (CONFIG.dragon_cap or 2) then dealCard("dragon", e.team) end
      else
        dealCard(e.mtype, e.team)
      end
    end
  end
end

local function summarise(title, events)
  local n = {}
  for _, e in ipairs(events) do n[e.t] = (n[e.t] or 0) + 1 end
  local bits = {}
  local names = {respawn = "respawned", heal = "healed at the fountain", decay = "structures decayed",
                 wave_spawn = "waves spawned", wave_move = "waves moved", wave_merge = "waves merged",
                 monster_spawn = "monsters up", monster_heal = "monsters healed", flip = "tiles flipped",
                 hit = "hits", kill = "champions killed", wave_down = "waves destroyed",
                 structure_down = "structures fell", monster_down = "monsters killed"}
  for k, label in pairs(names) do
    if n[k] then bits[#bits + 1] = n[k] .. " " .. label end
  end
  table.sort(bits)
  broadcastToAll(title .. (#bits > 0 and (": " .. table.concat(bits, ", ")) or ": nothing happened"),
    {0.85, 0.77, 0.6})
end

-- ---------------------------------------------------------------- phases
local function dragonCooldowns()
  for _, o in ipairs(tagged("hn:card:buff:dragon")) do
    local c = get(o)
    if c and c.track and c.track > 0 then o.call("hnSet", {track = c.track - 1}) end
  end
end

function doUpkeep()
  local s = readState()
  local events = CORE:upkeep(s)
  writeState(s, events)
  dragonCooldowns()
  S.phase, S.act = UPKEEP, 1
  summarise("Upkeep, round " .. S.round, events)
end

function doWorld()
  local s = readState()
  local events = CORE:world(s)
  writeState(s, events)
  summarise("World Phase", events)
end

local function announceWinner()
  if S.winner then
    broadcastToAll("GAME OVER: " .. seat(S.winner) .. " (" .. S.winner .. ") wins by "
      .. (S.end_reason or "?") .. " in round " .. S.round .. ".", {1, 0.9, 0.3})
  end
end

function doWinCheck()
  if S.winner then announceWinner(); return end
  if S.round >= CONFIG.round_limit then
    local w, why = CORE:tiebreak(readState())
    S.winner, S.end_reason = w, why
    if w then announceWinner()
    else broadcastToAll("GAME OVER: a draw at the round limit.", {1, 0.9, 0.3}); S.winner = "draw" end
  end
end

-- ------------------------------------------------------------ start game
local function basePlaces(team)
  local taken = {}
  local side = MAP[team]
  taken[Core.key(side.nexus)] = true
  for _, h in pairs(side.towers) do taken[Core.key(h)] = true end
  local out = {CORE.fountain[team]}
  for _, h in ipairs(CORE.tileHexes[CORE.baseTile[team]]) do
    if not taken[Core.key(h)] and Core.key(h) ~= Core.key(CORE.fountain[team]) then out[#out + 1] = h end
  end
  return out
end

local function takeFrom(container, tag, params)
  if not container then return false end
  for _, e in ipairs(container.getObjects()) do
    if e.gm_notes == tag then
      params.guid = e.guid
      container.takeObject(params)
      return true
    end
  end
  return false
end

local function nearXZ(o, p, r)
  local q = o.getPosition()
  return (q.x - p.x) ^ 2 + (q.z - p.z) ^ 2 <= r * r
end

function uiStartGame(player)
  if S.started then
    broadcastToAll("The game has started. Load a fresh copy of the save to start again.", {1, 0.6, 0.4})
    return
  end
  pcall(function() math.randomseed(os.time()) end)
  local picks, used = {north = {}, south = {}}, {}
  -- cards already put in a role slot are the draft; the rest is random
  for _, team in ipairs(TEAMS) do
    for _, o in ipairs(tagged("hn:card:champ:" .. team .. ":")) do
      local cid = tagOf(o):match(":([%w_]+)$")
      local role = ROSTER[cid] and ROSTER[cid].role
      if role and nearXZ(o, DASH[team].roles[role], 1.4) and not picks[team][role] then
        picks[team][role] = cid; used[cid] = true
      end
    end
  end
  for _, team in ipairs(TEAMS) do
    for _, role in ipairs(ROLES) do
      if not picks[team][role] then
        local pool = {}
        for cid, k in pairs(ROSTER) do
          if k.role == role and not used[cid] then pool[#pool + 1] = cid end
        end
        table.sort(pool)
        local cid = pool[math.random(#pool)]
        picks[team][role] = cid; used[cid] = true
      end
    end
  end
  for _, team in ipairs(TEAMS) do
    local d, rot, y = DASH[team], DASH[team].rot, dashY(team)
    local places = basePlaces(team)
    S.picks[team] = {}
    for i, role in ipairs(ROLES) do
      local cid = picks[team][role]
      S.picks[team][i] = cid
      local slot = d.roles[role]
      local ctag = "hn:card:champ:" .. team .. ":" .. cid
      local card = findTag(ctag)
      if card then
        card.setPositionSmooth({slot.x, y + 0.3, slot.z}, false, true)
        card.setRotation({0, rot, 0})
      else
        takeFrom(findTag("hn:deck:champ:" .. team), ctag,
          {position = {slot.x, y + 0.3, slot.z}, rotation = {0, rot, 0}, smooth = false})
      end
      local stag = "hn:champ:" .. team .. ":" .. cid
      local h = places[i] or places[1]
      local x, z = Core.hexToWorld(h, HEX_SIZE)
      local standee = findTag(stag)
      if standee then
        standee.setPositionSmooth({x, surfaceY(h) + 0.4, z}, false, true)
      else
        takeFrom(findTag("hn:bag:standees:" .. team), stag,
          {position = {x, surfaceY(h) + 0.6, z}, rotation = {0, rot, 0}, smooth = false})
      end
    end
    S.teams[team] = {kills = 0, towers_lost = 0, baron = false, dragons = 0}
  end
  S.started, S.round, S.priority, S.next_uid, S.winner = true, 0, FIRST_PLAYER, 1, nil
  broadcastToAll("Hex-Nexus: " .. seat("north") .. " " .. table.concat(S.picks.north, ", ")
    .. "  vs  " .. seat("south") .. " " .. table.concat(S.picks.south, ", "), {0.85, 0.77, 0.6})
  -- let the cards and standees land, then round 1's Upkeep
  Wait.time(function() doUpkeep(); moveMarkers(); refreshUI() end, 1.5)
end

-- ------------------------------------------------------------ table events
function hnCounterChanged(p)
  local o = getObjectFromGUID(p.guid)
  if not o then return end
  local st, tag = get(o), tagOf(o)
  local team = actingTeam(p.colour)
  local delta = p.after - p.before
  if not S.started then refreshUI(); return end
  if st.kind == "monster" or (st.kind == "wave" and team ~= st.team) then
    if delta < 0 then addAP(team, -delta) end             -- chips are AP (Rules 7)
  end
  if st.kind == "structure" and delta < 0 then
    local s = readState()
    for _, x in ipairs(s.structures) do
      if x.uid == st.uid then
        x.alive = true
        if not CORE:structureTargetable(s, x) then
          broadcastToAll("Careful: " .. (st.label or "that structure") .. " is protected "
            .. "(T1 before T2; a whole lane before the Nexus).", {1, 0.6, 0.4})
        end
      end
    end
  end
  if p.after == 0 and p.before > 0 then
    local s, events = readState(), {}
    if st.kind == "champion" then
      for _, c in ipairs(s.champs) do
        if c._obj == o then
          c._wasAlive = true
          CORE:killChampion(s, c, other(c.team), events)
          broadcastToAll(seat(c.team) .. " " .. ROSTER[c.cid].name .. " is down: " .. seat(other(c.team))
            .. " +" .. events[#events].ap .. " AP; back in " .. (c.track - 1) .. " rounds.", {1, 0.6, 0.4})
        end
      end
    elseif st.kind == "monster" then
      for _, m in ipairs(s.monsters) do
        if m._obj == o then
          m.alive, m.kind = true, "monster"
          CORE:destroy(s, m, team, events)
          broadcastToAll(seat(team) .. " takes the " .. st.label .. ".", {0.85, 0.77, 0.6})
        end
      end
    elseif st.kind == "structure" then
      for _, x in ipairs(s.structures) do
        if x._obj == o then
          x.alive, x.kind = true, "structure"
          CORE:destroy(s, x, team ~= x.team and team or nil, events)
          broadcastToAll(seat(x.team) .. " " .. st.label .. " falls.", {1, 0.6, 0.4})
        end
      end
    elseif st.kind == "wave" then
      for i, w in ipairs(s.waves) do
        if w._obj == o then table.remove(s.waves, i); break end
      end
    end
    writeState(s, events)
    if S.winner then announceWinner() end
  end
  refreshUI()
end

function hnUseAbility(p)
  local o = getObjectFromGUID(p.guid)
  local c = get(o)
  if not c then return end
  local a = c.ab[p.key]
  local who = seat(c.team) .. " " .. c.name
  if c.dead then broadcastToAll(who .. " is dead.", {1, 0.6, 0.4}); return end
  if c.track > 0 then broadcastToAll(who .. " is on cooldown (" .. c.track .. ").", {1, 0.6, 0.4}); return end
  if getAP(c.team) < a.cost then
    broadcastToAll(who .. ": " .. p.key .. " costs " .. a.cost .. " AP, the pool has " .. getAP(c.team) .. ".",
      {1, 0.6, 0.4})
    return
  end
  if S.phase ~= ACTION then broadcastToAll("(Not the Action Phase.)", {1, 0.8, 0.4}) end
  addAP(c.team, -a.cost)
  o.call("hnSet", {track = a.cd})
  broadcastToAll(who .. " uses " .. p.key .. " (" .. a.cost .. " AP): card out for " .. a.cd
    .. (a.cd == 1 and " round." or " rounds."), {0.85, 0.77, 0.6})
  refreshUI()
end

function hnPlayBuff(p)
  local o = getObjectFromGUID(p.guid)
  local c = get(o)
  if not c then return end
  local team = c.team or seatTeam(p.colour) or actingTeam(p.colour)
  if c.buff == "blue_buff" then
    local n = tonumber((ITEMS.buff.blue_buff.effect or ""):match("%+(%d+)%s*AP")) or 0
    addAP(team, n)
    broadcastToAll(seat(team) .. " plays Blue Buff: +" .. n .. " AP.", {0.85, 0.77, 0.6})
    o.destruct()
  elseif c.buff == "red_buff" then
    broadcastToAll(seat(team) .. " plays Red Buff: " .. ITEMS.buff.red_buff.effect
      .. " (click the target's HP).", {0.85, 0.77, 0.6})
    o.destruct()
  elseif c.buff == "dragon" then
    if (c.track or 0) > 0 then broadcastToAll("That Dragon card is on cooldown.", {1, 0.6, 0.4}); return end
    o.call("hnSet", {track = c.cd})
    broadcastToAll(seat(team) .. " plays a Dragon card: " .. (CONFIG.dragon_card and CONFIG.dragon_card.hits or 0)
      .. " hits on an adjacent unit (click its HP).", {0.85, 0.77, 0.6})
  else
    broadcastToAll("The Baron card is permanent: its waves are Empowered.", {0.85, 0.77, 0.6})
  end
  refreshUI()
end

function hnBuyItem(p)
  local o = getObjectFromGUID(p.guid)
  local c = get(o)
  if not c or c.bought then return end
  if S.phase ~= SHOP then broadcastToAll("(Items are bought in the Shop Phase.)", {1, 0.8, 0.4}) end
  if getAP(c.team) < c.cost then
    broadcastToAll(seat(c.team) .. " cannot afford " .. c.name .. " (" .. c.cost .. " AP).", {1, 0.6, 0.4})
    return
  end
  addAP(c.team, -c.cost)
  o.call("hnSet", {bought = true})
  broadcastToAll(seat(c.team) .. " buys " .. c.name .. " (" .. c.cost .. " AP).", {0.85, 0.77, 0.6})
  refreshUI()
end

function hnRefresh() refreshUI() end

-- ------------------------------------------------------------------- panel
function refreshUI()
  local row = ROUNDS[math.max(1, S.round)] or {}
  local phase = PHASES[S.phase] or "?"
  local p = priorityTeam()
  if not S.started then
    UI.setValue("hnRound", "Not started · press Start game")
  else
    UI.setValue("hnRound", "Round " .. S.round .. " / " .. CONFIG.round_limit .. "   ·   " .. phase)
  end
  local prio = "Priority (Player 1): " .. seat(p)
  if S.phase == ACTION and S.started then
    local who = SNAKE[S.act] == 1 and p or other(p)
    prio = prio .. "   ·   activation " .. S.act .. "/10: " .. seat(who)
  end
  if S.winner then prio = "GAME OVER: " .. (S.winner == "draw" and "draw" or (seat(S.winner) .. " wins")) end
  UI.setValue("hnPrio", prio)
  local bits = {}
  if row.spawn then bits[#bits + 1] = "waves spawn +" .. row.wave_size
  else bits[#bits + 1] = "no wave spawn" end
  if row.decays then
    bits[#bits + 1] = "decay -" .. CONFIG.structure_decay .. " (floors T" .. FLOORS.tower
      .. " / N" .. FLOORS.nexus .. ")"
  end
  bits[#bits + 1] = "kill = " .. row.kill_ap .. " AP (" .. row.kill_ap_baron .. " with Baron)"
  bits[#bits + 1] = "death: out " .. (row.death_pos - 1) .. " rnd"
  if row.monsters and row.monsters ~= "" then bits[#bits + 1] = "spawns: " .. row.monsters end
  UI.setValue("hnInfo", table.concat(bits, "   ·   "))
  local hint
  if not S.started then
    hint = "Put champion cards in your role slots to draft, or leave them empty: Start game fills the rest at random."
  elseif phase == "Upkeep" then
    hint = "Upkeep done automatically. Next phase ▶ starts the Action Phase."
  elseif phase == "Action" then
    hint = "Right-click a card to use an ability; click HP to hit. Next activation ▶ when done."
  elseif phase == "World" then
    hint = "World Phase resolved automatically. Next phase ▶ for the Shop."
  elseif phase == "Shop" then
    hint = "Player 1 then Player 2: right-click an item card → Buy."
  else
    hint = "Next phase ▶ starts the next round (its Upkeep runs automatically)."
  end
  UI.setValue("hnHint", hint)
  UI.setValue("hnAP", "AP:  " .. seat("north") .. " " .. getAP("north") .. "   ·   "
    .. seat("south") .. " " .. getAP("south"))
  UI.setAttribute("hnBody", "active", S.panel and "true" or "false")
end

function moveMarkers()
  local m = findTag("hn:marker:round")
  local slot = ROUND_SLOTS[math.max(1, S.round)]
  if m and slot then m.setPositionSmooth({slot.x, 2.2, slot.z}, false, true) end
  local pm = findTag("hn:marker:priority")
  local ps = PRIO_SLOTS[priorityTeam()]
  if pm and ps then pm.setPositionSmooth({ps.x, 2.2, ps.z}, false, true) end
end

function uiNextPhase()
  if S.winner then announceWinner(); return end
  if not S.started then broadcastToAll("Press Start game first.", {1, 0.8, 0.4}); return end
  if S.phase == UPKEEP then S.phase, S.act = ACTION, 1
  elseif S.phase == ACTION then S.phase = WORLD; doWorld()
  elseif S.phase == WORLD then S.phase = SHOP
  elseif S.phase == SHOP then S.phase = WINCHECK; doWinCheck()
  else doUpkeep() end
  moveMarkers()
  refreshUI()
end

function uiNextActivation()
  if S.phase ~= ACTION then return end
  if S.act < #SNAKE then S.act = S.act + 1 end
  refreshUI()
end

function uiRelayout(player)
  if player and not player.admin then
    broadcastToColor("Only the host or a promoted player can re-lay out the table.", player.color, {1, 0.5, 0.5})
    return
  end
  calibrate(true)
end

function uiFlipArt(player)
  if player and not player.admin then return end
  S.flip = ((S.flip or 0) + 180) % 360
  calibrate(true)
end

function uiTogglePanel()
  S.panel = not S.panel
  refreshUI()
end

-- ----------------------------------------------------------- camera / keys
local function mapView(colour)
  local pl = Player[colour]
  if not pl then return end
  local yaw = (colour == SEATS.north) and 180 or 0
  pl.lookAt({position = {x = 0, y = 1, z = 0}, pitch = 90, yaw = yaw, distance = 34})
end

function uiMapView(player) if player then mapView(player.color) end end

local function flipUnder(colour, hovered, pointer)
  local o = hovered
  if o and tagOf(o):find("^hn:tile:") then hnFlipTile({guid = o.getGUID()}); return end
  local p = (o and o.getPosition()) or pointer
  if not p then return end
  local h = CORE:worldToHex(p.x, p.z, HEX_SIZE)
  local t = h and tileObj(CORE:tile(h))
  if t then hnFlipTile({guid = t.getGUID()}) end
end

-- ---------------------------------------------------------------- lifecycle
function onSave()
  return JSON.encode(S)
end

function onLoad(saved)
  if saved and saved ~= "" then
    local ok, t = pcall(JSON.decode, saved)
    if ok and type(t) == "table" then for k, v in pairs(t) do S[k] = v end end
  end
  if addHotkey then
    addHotkey("Hex-Nexus: flip hexgroup", function(colour, hovered, pointer) flipUnder(colour, hovered, pointer) end)
    addHotkey("Hex-Nexus: map view", function(colour) mapView(colour) end)
  end
  Wait.frames(refreshUI, 5)
  Wait.time(refreshUI, 2, -1)
  if not S.calibrated then
    Wait.time(function() calibrate(true) end, 1)
  end
end
